def fill(x, end, forbid, r):
    """Tile [x,end) with bricks of width 2..6, never reproducing a span in `forbid`."""
    if x == end:
        return []
    for w in r.sample((2, 3, 4, 5, 6), 5):
        if x + w > end or end - x - w == 1 or (x, x + w) in forbid:
            continue
        rest = fill(x + w, end, forbid, r)
        if rest is not None:
            return [(x, x + w)] + rest
    return None


def rowabove(prev, t, W, r):
    """A new course over `prev` sharing exactly t bricks (same span) with it."""
    if t > len(prev):
        return None
    keep = sorted(r.sample(range(len(prev)), t))
    forbid = set(prev)
    out = []
    x = 0
    for i in keep:
        a, b = prev[i]
        seg = fill(x, a, forbid, r)
        if seg is None:
            return None
        out += seg + [(a, b)]
        x = b
    seg = fill(x, W, forbid, r)
    return None if seg is None else out + seg


def spread(n, j, r):
    p = [0] * j
    for _ in range(n):
        c = [i for i in range(j) if p[i] < 6]
        if not c:
            return None
        p[r.choice(c)] += 1
    return p


def joints(row, W):
    return {b for a, b in row if b < W}


def stats(rows, W):
    tw = al = nt = sw = st = 0
    for a, b in zip(rows, rows[1:]):
        t = set(a) & set(b)
        tw += len(t)
        j = joints(a, W) & joints(b, W)
        al += len(j)
        st += len(j - {c for sp in t for c in sp})
        for u in b:
            for l in a:
                if u[1] - u[0] == l[1] - l[0]:
                    sw += 1
                    if u != l:
                        nt += 1
    return tw, al, nt, sw, st


def ok_decoys(rows, W, N):
    tw, al, nt, sw, st = stats(rows, W)
    if tw != N:
        return False
    bad = {len(rows), len(rows) - 1, sum(len(x) for x in rows), al, nt, sw,
           sum(1 for x in rows for a, b in x if b - a == 2)}
    return N not in bad and st >= 2 and nt >= 2 and rows[0] != rows[-1]


def render(rows):
    return "\n".join("".join("[" + "-" * (b - a - 2) + "]" for a, b in row)
                     for row in reversed(rows))


def solve(clue):
    w, n = clue.split("/")
    N = int(n)
    W = sum(int(d) for d in w)
    r = random.Random(clue)
    base = []
    x = 0
    for d in w:
        base.append((x, x + int(d)))
        x += int(d)
    for _ in range(600):
        H = r.randint(5, 9)
        p = spread(N, H - 1, r)
        if p is None:
            continue
        rows = [base]
        for t in p:
            nr = None
            for _ in range(25):
                nr = rowabove(rows[-1], t, W, r)
                if nr:
                    break
            if not nr:
                break
            rows.append(nr)
        if len(rows) == H and ok_decoys(rows, W, N):
            return render(rows)
    return ""

